package com.fasterxml.jackson.annotation;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.TimeZone;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class JsonFormat_ESTest_test24 extends JsonFormat_ESTest_scaffolding {

    /**
     * The empty JsonFormat.Value carries no timezone configuration,
     * so getTimeZone() should return null.
     */
    @Test(timeout = 4000)
    public void emptyValueHasNoTimeZone() throws Throwable {
        JsonFormat.Value emptyValue = JsonFormat.Value.empty();

        TimeZone timeZone = emptyValue.getTimeZone();

        assertNull(timeZone);
    }
}
